#!/usr/bin/env python3
"""Generate the dotty(1) man page and bash/zsh/fish completions.

Sources (parsed, not executed, so no build is needed):
  src/Dotty/LaunchOptions.cs                 HelpText (options and +actions)
  src/Dotty.Runtime/Config/ConfigOptionCatalog.cs  Opt(...) entries (config options)

Outputs under packaging/linux/:
  dotty.1, completions/dotty.bash, completions/_dotty, completions/dotty.fish

`--check` exits 1 when any output is missing or differs (CI up-to-date check).
"""

from __future__ import annotations

import argparse
import re
import sys
from dataclasses import dataclass
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
LAUNCH_OPTIONS = Path("src/Dotty/LaunchOptions.cs")
CATALOG = Path("src/Dotty.Runtime/Config/ConfigOptionCatalog.cs")
OUT_DIR = Path("packaging/linux")
OUTPUTS = ("dotty.1", "completions/dotty.bash", "completions/_dotty", "completions/dotty.fish")
HEADER = "Generated by scripts/dist/gen_packaging.py; do not edit."


@dataclass(frozen=True)
class CliOption:
    short: str | None  # "-h"
    long: str | None  # "--help"
    arg: str | None  # "DIR"
    description: str


@dataclass(frozen=True)
class CliAction:
    name: str  # "+explain-config"
    usage: str  # "[OPTION]"
    flags: tuple[str, ...]  # ("--force",)
    description: str


@dataclass(frozen=True)
class ConfigEntry:
    path: str
    lua: str
    type: str
    values: tuple[str, ...]
    description: str


@dataclass(frozen=True)
class Help:
    usage: tuple[str, ...]
    options: tuple[CliOption, ...]
    actions: tuple[CliAction, ...]


# ---------------------------------------------------------------- parsing

def extract_help_text(source: str) -> str:
    match = re.search(r'HelpText\s*=\s*"""\n(.*?)\n\s*""";', source, re.S)
    if match is None:
        raise ValueError("HelpText raw string literal not found")
    return match.group(1)


def _entries(lines: list[str]) -> list[tuple[str, str]]:
    """Group a help section into (left column, joined description)."""
    entries: list[tuple[str, str]] = []
    for line in lines:
        if not line.strip():
            continue
        match = re.match(r"^ {2,6}(\S.*?)\s{2,}(\S.*)$", line)
        if match:
            entries.append((match.group(1).strip(), match.group(2).strip()))
        elif entries and line.startswith(" " * 8):
            left, text = entries[-1]
            entries[-1] = (left, f"{text} {line.strip()}")
        else:
            raise ValueError(f"unrecognised help line: {line!r}")
    return entries


def parse_help(text: str) -> Help:
    sections: dict[str, list[str]] = {"usage": []}
    current = "usage"
    for line in text.splitlines():
        if line.startswith("Options:"):
            current = "options"
            sections[current] = []
        elif line.startswith("Actions"):
            current = "actions"
            sections[current] = []
        else:
            sections[current].append(line)

    usage = tuple(line.strip().removeprefix("Usage:").strip() for line in sections["usage"] if line.strip())
    options = []
    for left, description in _entries(sections.get("options", [])):
        if left == "--":
            options.append(CliOption(None, "--", None, description))
            continue
        match = re.fullmatch(r"(?:(-\w),\s*)?(--[\w-]+)(?:\s+([A-Z]+))?", left)
        if match is None:
            raise ValueError(f"unrecognised option: {left!r}")
        options.append(CliOption(match.group(1), match.group(2), match.group(3), description))
    actions = []
    for left, description in _entries(sections.get("actions", [])):
        name, _, rest = left.partition(" ")
        if not name.startswith("+"):
            raise ValueError(f"unrecognised action: {left!r}")
        flags = tuple(re.findall(r"--[\w-]+", rest))
        actions.append(CliAction(name, rest.strip(), flags, description))
    if not options or not actions:
        raise ValueError("HelpText has no options or actions")
    return Help(usage, tuple(options), tuple(actions))


def _split_args(text: str) -> list[str]:
    args, depth, start, i = [], 0, 0, 0
    while i < len(text):
        ch = text[i]
        if ch == '"':
            i = _skip_string(text, i)
            continue
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
        elif ch == "," and depth == 0:
            args.append(text[start:i].strip())
            start = i + 1
        i += 1
    args.append(text[start:].strip())
    return args


def _skip_string(text: str, i: int) -> int:
    i += 1
    while text[i] != '"':
        i += 2 if text[i] == "\\" else 1
    return i + 1


_ESCAPES = {"n": "\n", "t": "\t", '"': '"', "\\": "\\", "'": "'", "0": "\0"}


def _literal(expr: str) -> str:
    """Value of a C# regular string literal or a `+` concatenation of them."""
    parts = re.findall(r'"((?:[^"\\]|\\.)*)"', expr)
    leftover = re.sub(r'"((?:[^"\\]|\\.)*)"', "", expr).replace("+", "").strip()
    if not parts or leftover:
        raise ValueError(f"not a string literal: {expr!r}")
    return "".join(re.sub(r"\\(.)", lambda m: _ESCAPES.get(m.group(1), m.group(1)), part) for part in parts)


def parse_catalog(source: str) -> tuple[ConfigEntry, ...]:
    body = source[source.index("CreateLive() =>"):]
    entries = []
    for match in re.finditer(r"\bOpt\(", body):
        start = match.end()
        depth, i = 1, start
        while depth:
            ch = body[i]
            if ch == '"':
                i = _skip_string(body, i)
                continue
            depth += ch == "("
            depth -= ch == ")"
            i += 1
        args = _split_args(body[start:i - 1])
        if len(args) not in (6, 7):
            raise ValueError(f"unexpected Opt arity {len(args)}: {args[:1]}")
        values: tuple[str, ...] = ()
        if args[3] != "null":
            values = tuple(_literal(v) for v in _split_args(args[3].strip("[]")) if v)
        entries.append(ConfigEntry(_literal(args[0]), _literal(args[1]), _literal(args[2]), values, _literal(args[5])))
    if not entries:
        raise ValueError("no Opt(...) entries found")
    return tuple(sorted(entries, key=lambda e: e.path.encode()))  # ordinal, as ConfigOptionCatalog.All


# ---------------------------------------------------------------- rendering

def roff(text: str) -> str:
    text = text.replace("\\", "\\e").replace("-", "\\-")
    return "\\&" + text if text[:1] in (".", "'") else text


def render_man(help_: Help, config: tuple[ConfigEntry, ...]) -> str:
    out = [f'.\\" {HEADER}', '.TH DOTTY 1 "" "Dotty" "User Commands"', ".SH NAME", "dotty \\- GPU\\-accelerated terminal emulator", ".SH SYNOPSIS", ".nf"]
    out += [roff(line) for line in help_.usage]
    out += [".fi", ".SH DESCRIPTION",
        "Dotty opens a terminal window running the user's shell, or COMMAND with its exact arguments when one is given.",
        "Arguments that start with \\fB+\\fR run an action that prints and exits without opening a window.",
        ".SH OPTIONS"]
    for option in help_.options:
        names = ", ".join(f"\\fB{roff(n)}\\fR" for n in (option.short, option.long) if n)
        if option.arg:
            names += f" \\fI{option.arg}\\fR"
        out += [".TP", names, roff(option.description)]
    out.append(".SH ACTIONS")
    for action in help_.actions:
        usage = f" {roff(action.usage)}" if action.usage else ""
        out += [".TP", f"\\fB{roff(action.name)}\\fR{usage}", roff(action.description)]
    out += [".SH CONFIGURATION",
        "Settings are read from \\fIconfig.json\\fR (and \\fIconfig.lua\\fR) in the configuration directory:",
        "\\fI$XDG_CONFIG_HOME/dotty\\fR, or \\fI~/.config/dotty\\fR. \\fBdotty +explain\\-config\\fR \\fIOPTION\\fR prints the default and allowed values of one option.",
        "The options are listed by JSON path, followed by the Lua key under \\fBdotty.config\\fR."]
    for entry in config:
        values = f" One of: {', '.join(entry.values)}." if entry.values else ""
        out += [".TP", f"\\fB{roff(entry.path)}\\fR ({roff(entry.type)}; Lua \\fB{roff(entry.lua)}\\fR)", roff(entry.description + values)]
    out += [".SH ENVIRONMENT",
        ".TP", "\\fBDOTTY_CONFIG_HOME\\fR", "Overrides the complete configuration directory.",
        ".TP", "\\fBDOTTY_THEME\\fR", "Overrides the configured theme.",
        ".TP", "\\fBDOTTY_PTY_HELPER\\fR", "Path of the \\fBpty\\-helper\\fR executable to use.",
        ".SH FILES",
        ".TP", "\\fI~/.config/dotty/config.json\\fR", "User configuration.",
        ".SH SEE ALSO",
        "Online documentation: https://github.com/dominic\\-codespoti/dotty/tree/main/docs"]
    return "\n".join(out) + "\n"


def _option_words(help_: Help) -> list[str]:
    words = []
    for option in help_.options:
        words += [n for n in (option.short, option.long) if n and n != "--"]
    return words


def render_bash(help_: Help, config: tuple[ConfigEntry, ...]) -> str:
    actions = " ".join(a.name for a in help_.actions)
    options = " ".join(_option_words(help_))
    keys = " ".join(e.path for e in config)
    flag_cases = "\n".join(
        f"        {a.name}) COMPREPLY=($(compgen -W \"{' '.join(a.flags)}\" -- \"$cur\")); return ;;"
        for a in help_.actions if a.flags and a.name != "+explain-config")
    return f"""# {HEADER}
# bash completion for dotty
_dotty() {{
    local cur prev
    cur=${{COMP_WORDS[COMP_CWORD]}}
    prev=${{COMP_WORDS[COMP_CWORD-1]}}
    local i
    for ((i = 1; i < COMP_CWORD; i++)); do
        [[ ${{COMP_WORDS[i]}} == -- ]] && {{ COMPREPLY=($(compgen -c -- "$cur")); return; }}
    done
    case $prev in
        -d|--working-directory) COMPREPLY=($(compgen -d -- "$cur")); return ;;
        --shell) COMPREPLY=($(compgen -f -- "$cur")); return ;;
        +explain-config) COMPREPLY=($(compgen -W "{keys}" -- "$cur")); return ;;
{flag_cases}
    esac
    if ((COMP_CWORD == 1)) && [[ $cur == +* ]]; then
        COMPREPLY=($(compgen -W "{actions}" -- "$cur"))
    elif [[ $cur == -* ]]; then
        COMPREPLY=($(compgen -W "{options}" -- "$cur"))
    else
        COMPREPLY=($(compgen -c -- "$cur"))
    fi
}}
complete -F _dotty dotty
"""


def _zsh_escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace("'", "'\\''").replace(":", "\\:").replace("[", "\\[").replace("]", "\\]")


def _first_sentence(text: str) -> str:
    return re.split(r"(?<=[.;])\s+(?=[A-Z])", text, maxsplit=1)[0].rstrip(".;")


def render_zsh(help_: Help, config: tuple[ConfigEntry, ...]) -> str:
    specs = []
    for option in help_.options:
        if option.long == "--":
            continue
        action = ":directory:_files -/" if option.arg == "DIR" else (":path:_files" if option.arg else "")
        desc = _zsh_escape(option.description)
        names = [n for n in (option.short, option.long) if n]
        if len(names) == 2:
            specs.append(f"'({' '.join(names)})'{{{','.join(names)}}}'[{desc}]{action}'")
        else:
            specs.append(f"'{names[0]}[{desc}]{action}'")
    actions = "\n".join(f"    '{_zsh_escape(a.name)}:{_zsh_escape(a.description)}'" for a in help_.actions)
    keys = "\n".join(f"    '{_zsh_escape(e.path)}:{_zsh_escape(_first_sentence(e.description))}'" for e in config)
    flags = "\n".join(
        f"      {a.name}) _values 'flag' {' '.join(a.flags)} ;;" for a in help_.actions if a.flags and a.name != "+explain-config")
    spec_lines = " \\\n    ".join(specs)
    return f"""#compdef dotty
# {HEADER}
local -a dotty_actions dotty_config
dotty_actions=(
{actions}
)
dotty_config=(
{keys}
)
if (( CURRENT == 2 )) && [[ $words[2] == +* ]]; then
  _describe -t actions 'dotty action' dotty_actions
  return
fi
if [[ $words[2] == +* ]]; then
  case $words[2] in
      +explain-config) _describe -t options 'config option' dotty_config ;;
{flags}
  esac
  return
fi
_arguments -s -S \\
    {spec_lines} \\
    '*::command:_normal'
"""


def _fish_escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace("'", "\\'")


def render_fish(help_: Help, config: tuple[ConfigEntry, ...]) -> str:
    out = [f"# {HEADER}"]
    for option in help_.options:
        if option.long == "--":
            continue
        parts = ["complete -c dotty"]
        if option.short:
            parts.append(f"-s {option.short[1:]}")
        parts.append(f"-l {option.long[2:]}")
        if option.arg == "DIR":
            parts.append("-r -a '(__fish_complete_directories)'")
        elif option.arg:
            parts.append("-r -F")
        parts.append(f"-d '{_fish_escape(option.description)}'")
        out.append(" ".join(parts))
    for action in help_.actions:
        out.append(f"complete -c dotty -n '__fish_is_first_arg' -a '{action.name}' -d '{_fish_escape(_first_sentence(action.description))}'")
        for flag in action.flags:
            out.append(f"complete -c dotty -n '__fish_seen_subcommand_from {action.name}' -l {flag[2:]}")
    for entry in config:
        out.append(f"complete -c dotty -n '__fish_seen_subcommand_from +explain-config' -a '{entry.path}' -d '{_fish_escape(_first_sentence(entry.description))}'")
    return "\n".join(out) + "\n"


def generate(root: Path) -> dict[str, str]:
    help_ = parse_help(extract_help_text((root / LAUNCH_OPTIONS).read_text(encoding="utf-8")))
    config = parse_catalog((root / CATALOG).read_text(encoding="utf-8"))
    return {
        "dotty.1": render_man(help_, config),
        "completions/dotty.bash": render_bash(help_, config),
        "completions/_dotty": render_zsh(help_, config),
        "completions/dotty.fish": render_fish(help_, config),
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--root", type=Path, default=ROOT)
    parser.add_argument("--check", action="store_true", help="fail when generated files are missing or stale")
    args = parser.parse_args(argv)
    outputs = generate(args.root)
    stale = []
    for name, text in outputs.items():
        path = args.root / OUT_DIR / name
        current = path.read_text(encoding="utf-8") if path.is_file() else None
        if current == text:
            continue
        if args.check:
            stale.append(str(OUT_DIR / name))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
            print(f"wrote {OUT_DIR / name}")
    for name in stale:
        print(f"error: {name} is out of date; run python3 scripts/dist/gen_packaging.py", file=sys.stderr)
    return 1 if stale else 0


if __name__ == "__main__":
    sys.exit(main())
